"""Render docs/commands.md from the CLI's own schema.

The command reference is generated from `tplinkctl schema`, which is itself
derived from the argparse tree, so the docs cannot drift from what the binary
accepts. `make contract` fails if the checked-in file is stale.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any

from . import cli

HEADER = """# Command reference

<!-- Generated by `python -m tplink_admin.clidoc > docs/commands.md`. Do not edit by hand. -->

Generated from `tplinkctl schema`, the clispec v0.2 contract the binary emits
about itself. **Mutating** commands change router state or write local files;
router mutations accept `--plan`/`--dry-run` and need `--yes` (or `confirm=true`
over MCP) to run. Profiles can block any command; see
[`src/tplink_admin/profiles/`](../src/tplink_admin/profiles/).
"""


def _cell(text: Any) -> str:
    return str(text).replace("|", "\\|").replace("\n", " ")


def _arg_rows(args: list[dict[str, Any]]) -> list[str]:
    rows = ["| Argument | Type | Required | Values / default | Description |", "|---|---|---|---|---|"]
    for arg in args:
        values = []
        if arg.get("enum"):
            values.append(", ".join(f"`{v}`" for v in arg["enum"]))
        if "default" in arg:
            values.append(f"default `{arg['default']}`")
        rows.append("| `{}` | {} | {} | {} | {} |".format(
            arg["name"], arg["type"], "yes" if arg.get("required") else "", _cell("; ".join(values)),
            _cell(arg.get("description", ""))))
    return rows


def render(document: dict[str, Any] | None = None) -> str:
    doc = cli.schema_document() if document is None else document
    lines = [HEADER, "## Global options", "", *_arg_rows(doc["global_args"]), "", "## Commands", ""]
    lines += ["| Command | Mutating | Description |", "|---|---|---|"]
    for command in doc["commands"]:
        anchor = command["name"].replace(" ", "-")
        lines.append(f"| [`{command['name']}`](#{anchor}) | {'yes' if command['mutating'] else ''} | "
                     f"{_cell(command['description'])} |")
    for command in doc["commands"]:
        lines += ["", f"### {command['name']}", "", command["description"].rstrip(".") + "."]
        facts = []
        if command["mutating"]:
            facts.append("**Mutating.**")
        if command["stability"] != "stable":
            facts.append(f"Stability: {command['stability']}.")
        if command.get("note"):
            facts.append(command["note"])
        if facts:
            lines += ["", " ".join(facts)]
        lines += ["", f"```\ntplinkctl {command['name']}" + "".join(
            f" <{a['name']}>" if a.get("required") and not a["name"].startswith("--") else ""
            for a in command.get("args", [])) + "\n```"]
        if command.get("args"):
            lines += ["", *_arg_rows(command["args"])]
    lines += ["", "## Exit codes", "", "| Code | Kind | Retryable | Meaning |", "|---|---|---|---|"]
    for error in sorted(doc["errors"], key=lambda e: e["exit_code"]):
        lines.append(f"| `{error['exit_code']}` | `{error['kind']}` | {'yes' if error.get('retryable') else ''} | "
                     f"{_cell(error.get('description', ''))} |")
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", type=Path, help="fail if the checked-in reference differs from generation")
    args = parser.parse_args(argv)
    output = render()
    if args.check:
        if not args.check.exists() or args.check.read_text(encoding="utf-8") != output:
            print("Command reference is stale; regenerate with "
                  "python -m tplink_admin.clidoc > docs/commands.md", file=sys.stderr)
            return 1
        return 0
    sys.stdout.write(output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
